BEGIN TRANSACTION;
CREATE TABLE coverage(
 mode TEXT,domain TEXT,reached INTEGER,total INTEGER,fraction REAL,
 PRIMARY KEY(mode,domain));
CREATE TABLE equations(
 id TEXT PRIMARY KEY,label TEXT,ascii TEXT,status TEXT);
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE native_bindings(
 id TEXT PRIMARY KEY,rainbow_role TEXT,native_handle TEXT,fit TEXT,note TEXT);
CREATE TABLE open_edges(
 id TEXT PRIMARY KEY,edge TEXT,status TEXT,closure_target TEXT);
CREATE TABLE overlay_edges(
 id TEXT PRIMARY KEY,source TEXT,relation TEXT,target TEXT,status TEXT);
CREATE TABLE overlay_objects(
 id TEXT PRIMARY KEY,name TEXT,uri TEXT UNIQUE,kind TEXT,status TEXT,definition TEXT);
CREATE TABLE roadmap_steps(
 id TEXT PRIMARY KEY,ordinal INTEGER,title TEXT,verdict TEXT);
PRAGMA writable_schema=ON;
CREATE TABLE 'search_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'search_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3, c4);
CREATE TABLE 'search_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'search_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'search_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
PRAGMA writable_schema=OFF;
COMMIT;
